import {bridgeScenes,bridgeScene,bridgeWords,bridgeOpening,bridgeTeaching} from './sentence-bridges-content.mjs';
import {initialBridges,changeBridges,bridgesPresentation,bridgesNarration,bridgesAnnouncement} from './sentence-bridges-core.mjs';
import {detailCopy,detailTeaching,detailModel,detailScenes} from './sentence-details-content.mjs';
import {initialDetails,changeDetails,detailsNarration,detailsAnnouncement} from './sentence-details-core.mjs';
import {detailsView,initialDetailsView,detailPage} from './sentence-details-ui.mjs';
import {groupCopy} from './sentence-groups-content.mjs';
import {initialGroups,changeGroups,groupsPresentation,groupsNarration} from './sentence-groups-core.mjs';
import {groupsView,initialGroupsView} from './sentence-groups-ui.mjs';
import {hearButton,stopSpeech,bindSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,owner=null,mode='joins',details=null,detailsUi=null,joinsUi=null,groups=null,groupsUi=null,mountToken=0;
export function resetBridgesSession(){session=null;owner=null;mode='joins';details=null;detailsUi=null;joinsUi=null;groups=null;groupsUi=null;mountToken++;}
function current(id){if(owner!==id||!session){resetBridgesSession();session=initialBridges();details=initialDetails();detailsUi=initialDetailsView();joinsUi={teachingOpen:false,talkOpen:false};groups=initialGroups();groupsUi=initialGroupsView();owner=id;}return session;}
const modes=['joins','details','groups'];
const modeLabel=value=>value==='groups'?groupCopy.tab:detailCopy[value];
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const button=(action,value,label,selected=false,disabled=false)=>`<button type="button" data-bridges-action="${action}" data-bridges-value="${value}"${['scene','word'].includes(action)?` aria-pressed="${selected}"`:''}${disabled?' disabled':''}>${selected?'<span aria-hidden="true">✓ </span>':''}${esc(label)}</button>`;
function joinsView(s){const c=bridgeScene(s.caseId),p=bridgesPresentation(s);return `<header><a href="#loft">Story Loft</a><h1>Sentence Bridges</h1><p>${esc(bridgeOpening)}</p></header><div class="bridges-layout"><section class="bridges-source"><h2>Our scene</h2><h3>${esc(c.title)}</h3><p>${esc(c.context)}</p><p><strong>Purpose:</strong> ${esc(c.purpose)}</p><h2>Choose a scene</h2><div class="bridges-scenes">${bridgeScenes.map(x=>button('scene',x.id,x.label,s.caseId===x.id)).join('')}</div><p>Another scene starts its two separate sentences. This visit is not saved.</p></section><section class="bridges-trial"><h2>Choose a joining word</h2><div class="bridges-words">${bridgeWords.map(w=>button('word',w,w,s.bridge===w)).join('')}</div><div class="bridges-assembly" aria-label="Sentence strips"><p class="bridges-strip"><span class="bridges-id">${p.strips[0].id}</span> ${esc(p.strips[0].text)}</p>${s.bridge?`<div class="bridges-span">${esc(s.bridge)}</div>`:'<div class="bridges-gap" aria-hidden="true"></div>'}<p class="bridges-strip"><span class="bridges-id">${p.strips[1].id}</span> ${esc(p.strips[1].text)}</p></div><h2 id="bridges-trial-title" tabindex="-1">Sentence we are trying</h2><p class="bridges-output">${esc(p.trial)}</p><aside class="bridges-meaning"><h2>Meaning to notice</h2><p>${esc(p.meaning)}</p></aside><div class="bridges-edits">${button('swap','','Swap sentence order')}${button('separate','','Separate sentences',false,!s.bridge)}${!s.bridge?'<p>The sentences are already separate.</p>':''}${button('undo','','Undo last change',false,!s.previous)}${!s.previous?'<p>No change to undo.</p>':''}</div>${hearButton(bridgesNarration(s),'Hear this trial')}<details class="bridges-teaching"><summary>What do these joining words do?</summary><p>${esc(bridgeTeaching)}</p><p>Here each starting strip has a subject and a verb.</p></details><details class="bridges-talk"><summary>Talk together</summary><p>Which words came from our scene? What connection does your joining word add? What would need to change in the scene for another reading to fit?</p></details></section></div><footer><a href="#loft">Return to Story Loft</a><a href="#post/messages">Try a message for a reader</a><a href="#post/instructions">Try an instruction strip</a></footer>`;}
export function bridgesEntry(){return '<p class="bridges-entry"><a class="secondary" href="#loft/bridges">Sentence Bridges: keep the scene, change the relation</a></p>';}
function view(){return `<header><a href="#loft">Story Loft</a><h1>Sentence Bridges</h1></header><div class="bridges-modes" role="tablist" aria-label="${esc(detailCopy.modes)}">${modes.map(value=>`<button type="button" id="bridges-tab-${value}" role="tab" data-bridges-mode-choice="${value}" aria-controls="bridges-mode-panel" aria-selected="${mode===value}" tabindex="${mode===value?'0':'-1'}">${esc(modeLabel(value))}</button>`).join('')}</div><div id="bridges-mode-panel" role="tabpanel" aria-labelledby="bridges-tab-${mode}">${mode==='groups'?groupsView(groups,groupsUi):mode==='details'?detailsView(details,detailsUi):joinsView(session).replace(/<header>.*?<\/header>/s,`<p>${esc(bridgeOpening)}</p>`)}</div>${mode!=='joins'?'<footer><a href="#loft">Return to Story Loft</a></footer>':''}`;}
export function bridgesPage(explorerId){current(explorerId);mountToken++;return `<section class="bridges-page" data-bridges-mode="${mode}"><div data-bridges-view>${view()}</div><p id="bridges-status" role="status" aria-live="polite"></p></section>`;}
function bindingGuard(root,valid){
 const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details')].filter(n=>!n.closest?.('.speech-controls')),chains=new Map(),retired=new WeakSet();
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid())observer.disconnect();});observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return node=>{audit(observer.takeRecords());if(!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;
  for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;
 };
}
export function bindBridges({explorerId,focus}){
 const root=document.querySelector('.bridges-page');if(!root)return;
 const capturedOwner=explorerId();current(capturedOwner);
 const capturedMode=mode,capturedToken=mountToken,capturedParent=root.parentNode;
 const capturedGroups=groups,capturedGroupBytes=mode==='groups'?bytes(groups):null;
 const live=()=>root.isConnected&&root.parentNode===capturedParent&&document.querySelector('.bridges-page')===root&&location.hash==='#loft/bridges'&&explorerId()===capturedOwner&&owner===capturedOwner&&mode===capturedMode&&mountToken===capturedToken&&(capturedMode!=='groups'||groups===capturedGroups&&capturedGroupBytes!==null&&bytes(groups)===capturedGroupBytes);
 const accepts=bindingGuard(root,live);
 const guard=control=>()=>accepts(control);
 for(const control of root.querySelectorAll('button,input,select,a,summary,details')){if(control.closest('.speech-controls'))continue;for(const type of ['click','input','change','keydown'])control.addEventListener(type,event=>{if(!accepts(control)){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});}
 const snapshot=()=>{if(!live())return;if(mode==='joins'){joinsUi.teachingOpen=root.querySelector('.bridges-teaching').open;joinsUi.talkOpen=root.querySelector('.bridges-talk').open;}else if(mode==='details')for(const kind of ['teaching','model','grownup'])detailsUi[kind+'Open']=root.querySelector(`[data-details-panel="${kind}"]`).open;else for(const kind of ['facts','talk','grownup']){const panel=root.querySelector(`[data-groups-panel="${kind}"]`);if(panel)groupsUi[kind+'Open']=panel.open;}};
 const focusAt=selector=>{let node=root.querySelector(selector);if(!node||node.disabled||!node.getClientRects().length){selector=mode==='groups'?'#groups-task':'[role=tab][aria-selected=true]';node=root.querySelector(selector);}if(focus)focus(selector);else node?.focus();};
 const redraw=(selector,announcement)=>{stopSpeech();mountToken++;root.dataset.bridgesMode=mode;root.querySelector('[data-bridges-view]').innerHTML=view();bindBridges({explorerId,focus});bindSpeech();if(announcement)root.querySelector('#bridges-status').textContent=announcement;if(selector)focusAt(selector);};
 const chooseMode=(value)=>{if(!modes.includes(value)||value===mode)return;snapshot();mode=value;redraw(`[data-bridges-mode-choice="${value}"]`,modeLabel(value));if(value==='details'){const scene=root.querySelector('.details-scene'),rect=scene.getBoundingClientRect();if(rect.top<0||rect.top>innerHeight-100)scene.scrollIntoView({block:'start'});}};
 root.querySelectorAll('[data-bridges-mode-choice]').forEach(control=>{const valid=guard(control);control.addEventListener('click',()=>{if(valid())chooseMode(control.dataset.bridgesModeChoice);});control.addEventListener('keydown',event=>{if(!valid()||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();chooseMode(event.key==='Home'?modes[0]:event.key==='End'?modes.at(-1):modes[(modes.indexOf(mode)+(event.key==='ArrowRight'?1:modes.length-1))%modes.length]);});});
 if(mode==='joins'){
  for(const [selector,key] of [['.bridges-teaching','teachingOpen'],['.bridges-talk','talkOpen']]){const panel=root.querySelector(selector);panel.open=joinsUi[key];const valid=guard(panel);panel.addEventListener('toggle',()=>{if(!valid()||joinsUi[key]===panel.open)return;joinsUi[key]=panel.open;stopSpeech();});}
  root.querySelectorAll('[data-bridges-action]').forEach(control=>{const valid=guard(control);control.addEventListener('click',()=>{
   if(!valid())return;const action=control.dataset.bridgesAction,next=changeBridges(session,action,control.dataset.bridgesValue);if(!next)return;snapshot();session=next;
   redraw(action==='word'?`[data-bridges-action="word"][data-bridges-value="${session.bridge}"]`:action==='scene'?`[data-bridges-action="scene"][data-bridges-value="${session.caseId}"]`:action==='swap'?'[data-bridges-action="swap"]':'#bridges-trial-title',bridgesAnnouncement(session,action));
  });});
 }else if(mode==='details'){
  for(const kind of ['teaching','model','grownup']){const panel=root.querySelector(`[data-details-panel="${kind}"]`),valid=guard(panel);panel.addEventListener('toggle',()=>{if(!valid()||detailsUi[kind+'Open']===panel.open)return;detailsUi[kind+'Open']=panel.open;stopSpeech();});}
  root.querySelectorAll('[data-details-action]').forEach(control=>{const valid=guard(control);control.addEventListener('click',()=>{
   if(!valid())return;const action=control.dataset.detailsAction;
   if(action.startsWith('teaching-')||action.startsWith('model-')){const [kind,direction]=action.split('-'),items=kind==='teaching'?detailTeaching:detailModel,currentPage=detailPage(detailsUi[kind+'Page'],items.length),next=detailPage(currentPage+(direction==='next'?1:-1),items.length);if(next===currentPage)return;snapshot();detailsUi[kind+'Page']=next;redraw(`#details-${kind}-title`,`${detailCopy[kind+'Count']} ${next+1} of ${items.length}`);return;}
   let coreAction=action,value=control.dataset.detailsValue;if(action.startsWith('scene-')){const index=detailScenes.findIndex(x=>x.id===details.caseId),next=index+(action==='scene-next'?1:-1);if(!detailScenes[next])return;coreAction='scene';value=detailScenes[next].id;}
   const next=changeDetails(details,coreAction,value);if(!next)return;snapshot();details=next;redraw(coreAction==='attach'?`[data-details-action="attach"][data-details-value="${value}"]`:coreAction==='scene'?'#details-scene-title':'#details-sentence-title',detailsAnnouncement(details,coreAction));
  });});
  root.querySelectorAll('[data-details-link]').forEach(control=>{const valid=guard(control);control.addEventListener('click',event=>{event.preventDefault();if(valid())focusAt(`#details-figure-${control.dataset.detailsLink}`);});});
 }
 if(mode==='groups'){
  const announce=(action,value)=>{const p=groupsPresentation(groups),copy=groupCopy;let text=action==='scene'?copy.sceneAnnouncement:action==='mark'?(p.marked.includes(value)?copy.markedAnnouncement:copy.unmarkedAnnouncement):action==='check'?copy.checkAnnouncement:action==='page'?(value==='meaning'?copy.revealAnnouncement:copy.editAnnouncement):action.startsWith('teaching-')?(action==='teaching-close'?copy.returnAnnouncement:copy.teachingAnnouncement):copy.wordingAnnouncement;
   return text.replaceAll('{title}',p.scene.title).replaceAll('{label}',p.scene.members.find(m=>m.id===value)?.label||'').replaceAll('{n}',String(groups.teachingStep+1));};
  const apply=(control,action,value,target='#groups-task')=>{if(!accepts(control))return;const next=changeGroups(groups,action,value);if(!next)return;snapshot();groups=next;redraw(target,announce(action,value));};
  root.querySelectorAll('[data-groups-panel]').forEach(panel=>{const valid=guard(panel);panel.addEventListener('toggle',()=>{if(!valid())return;groupsUi[panel.dataset.groupsPanel+'Open']=panel.open;});});
  root.querySelector('[data-groups-scene]')?.addEventListener('change',event=>apply(event.currentTarget,'scene',event.currentTarget.value,'#groups-scene'));
  root.querySelectorAll('[data-groups-member]').forEach(control=>control.addEventListener('change',()=>apply(control,'mark',control.dataset.groupsMember,`[data-groups-member="${control.dataset.groupsMember}"]`)));
  root.querySelectorAll('[data-groups-action]').forEach(control=>control.addEventListener('click',()=>{const action=control.dataset.groupsAction,value=action==='teaching-step'?Number(control.dataset.groupsValue):control.dataset.groupsValue;
   apply(control,action,value,action==='teaching-open'||action==='teaching-step'?'#groups-teaching-title':action==='commas'?'[data-groups-action="commas"]':'#groups-task');}));
 }
 root.querySelectorAll('[data-speak]').forEach(control=>{const valid=guard(control);control.addEventListener('click',event=>{if(!valid()){event.preventDefault();event.stopImmediatePropagation();return;}snapshot();control.dataset.speak=mode==='groups'?groupsNarration(groups,groupsUi):mode==='joins'?bridgesNarration(session):detailsNarration(details,detailsUi);},{capture:true});});
}
